import { AndroidConfig } from "@expo/config-plugins";

import {
  MIN_SDK_VERSION_PROPERTY,
  REQUIRED_MIN_SDK_VERSION,
  setAndroidMinSdkVersion,
} from "../setAndroidMinSdkVersion";

const { parsePropertiesFile, propertiesListToString } =
  AndroidConfig.Properties;

// Trimmed-down version of the gradle.properties generated by `npx expo prebuild`.
const makeProperties = (extra = "") => `# Project-wide Gradle settings.
org.gradle.jvmargs=-Xmx2048m -XX:MaxMetaspaceSize=512m

android.useAndroidX=true
${extra}
newArchEnabled=true
hermesEnabled=true
`;

const getMinSdkVersion = (contents: string) =>
  parsePropertiesFile(contents).find(
    (item) => item.type === "property" && item.key === MIN_SDK_VERSION_PROPERTY,
  );

const apply = (contents: string) =>
  propertiesListToString(
    setAndroidMinSdkVersion(parsePropertiesFile(contents)),
  );

describe("setAndroidMinSdkVersion", () => {
  it("requires Android 8.0 (API 26), where AHardwareBuffer was introduced", () => {
    expect(REQUIRED_MIN_SDK_VERSION).toBe(26);
  });

  it("adds android.minSdkVersion when the app does not set it", () => {
    const result = apply(makeProperties());
    expect(getMinSdkVersion(result)).toEqual({
      type: "property",
      key: MIN_SDK_VERSION_PROPERTY,
      value: "26",
    });
    // The other properties are kept as they were.
    expect(result).toContain("android.useAndroidX=true");
    expect(result).toContain("hermesEnabled=true");
  });

  it("raises a lower android.minSdkVersion (Expo's default is 24)", () => {
    const result = apply(makeProperties("android.minSdkVersion=24"));
    expect(getMinSdkVersion(result)).toMatchObject({ value: "26" });
    expect(result.match(/android\.minSdkVersion=/g)).toHaveLength(1);
  });

  it("raises a value that is not a number", () => {
    const result = apply(makeProperties("android.minSdkVersion=oops"));
    expect(getMinSdkVersion(result)).toMatchObject({ value: "26" });
  });

  it("keeps a higher android.minSdkVersion", () => {
    const contents = makeProperties("android.minSdkVersion=28");
    expect(apply(contents)).toBe(contents);
  });

  it("keeps the exact floor", () => {
    const contents = makeProperties("android.minSdkVersion=26");
    expect(apply(contents)).toBe(contents);
  });

  it("is idempotent", () => {
    const once = apply(makeProperties("android.minSdkVersion=24"));
    expect(apply(once)).toBe(once);
  });

  it("returns the same list when nothing changes", () => {
    const properties = parsePropertiesFile(
      makeProperties("android.minSdkVersion=30"),
    );
    expect(setAndroidMinSdkVersion(properties)).toBe(properties);
  });

  it("honours a custom floor", () => {
    const properties = parsePropertiesFile(
      makeProperties("android.minSdkVersion=24"),
    );
    expect(
      propertiesListToString(setAndroidMinSdkVersion(properties, 29)),
    ).toContain("android.minSdkVersion=29");
  });
});
